/* Example: fixed header styling */
header {
    position: fixed;
    top: 0;
    width: 100%;
    background-color: #222;
}

/* Example styling for a content section */
#section1 {
    background-color: lightblue;
    padding: 2rem;
    margin: 1rem 0;
}

/* Example: adding scroll-margin to an element */
#myElement {
    scroll-margin-top: 50px;
}

/* Testing a CSS property effect */
/* After applying margin-top: 20px to an element, */
/* you would test it by checking the visual spacing. */

/* Applying consistent margin to multiple elements */
#item1, #item2, #item3 {
    margin-top: 20px;
}

/* Similar: adding scroll padding to a container */
html {
    scroll-padding-top: 60px;
}

/* Adjusting scroll-margin and scroll-padding values */
#target-element {
    scroll-margin-top: 50px;
}
html {
    scroll-padding-top: 30px;
}
